        (10.5, 2),
        (12.0, 3),
        (11.5, 1)
    ]
    result = calculate_weighted_average(sample_data)
    print(result)

def calculate_weighted_average(measurements, category_weights):
    if not measurements or not category_weights:
        return 0.0
    if len(measurements) != len(category_weights):
        raise ValueError("Measurements and category weights must have the same length")
    total_weighted_value = 0.0
    total_weights = 0.0
    for i in range(len(measurements)):
        value = measurements[i]
        weight = category_weights[i]
        total_weighted_value += value * weight
        total_weights += weight
    if total_weights == 0:
        return 0.0
    return total_weighted_value / total_weights

if __name__ == '__main__':
    sample_measurements = [10.5, 20.0, 15.5, 30.0]
    sample_weights = [1, 2, 1, 4]
    result = calculate_weighted_average(sample_measurements, sample_weights)
    print(result)

import functools

class WeightTypeException(Exception):
    def __init__(self, value):
        super().__init__("Invalid type for weight: {}".format(type(value).__name__))

class WeightRangeException(Exception):
    def __init__(self, value):
        super().__init__("Invalid weight value: {}".format(value))

MAX_VALID_WEIGHT = 500.0
MIN_VALID_WEIGHT = 0.0

def ensure_valid_weight(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if len(args) < 1:
            raise WeightTypeException(None)

        raw_value = args[0]

        if isinstance(raw_value, bool):
            raise WeightTypeException(raw_value)

        if not isinstance(raw_value, (int, float)):
            raise WeightTypeException(raw_value)

        if raw_value < MIN_VALID_WEIGHT or raw_value > MAX_VALID_WEIGHT:
            raise WeightRangeException(raw_value)

        normalized_weight = float(raw_value)
        return func(normalized_weight, *args[1:], **kwargs)
    return wrapper

@ensure_valid_weight
def compute_mass_kg(weight):
    return weight

@ensure_valid_weight
def convert_to_pounds(weight):
    conversion_factor = 2.20462
    return weight * conversion_factor

