MIN_VALID_WEIGHT = 0.0
MAX_VALID_WEIGHT = 2000.0

class WeightTypeException(TypeError):
    def __init__(self, value):
        self.value = value
        if isinstance(value, bool):
            super().__init__("Weight cannot be a boolean value.")
        else:
            super().__init__("Weight must be a numeric type (int or float), not {}.".format(type(value).__name__))

class WeightValueException(ValueError):
    def __init__(self, value):
        self.value = value
        if value < MIN_VALID_WEIGHT:
            super().__init__("Weight cannot be negative. Received: {}.".format(value))
        else:
            super().__init__("Weight exceeds maximum allowed limit of {}. Received: {}.".format(MAX_VALID_WEIGHT, value))

def normalize_weight_input(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if not args:
            raise WeightTypeException("Missing required weight argument.")

        weight_candidate = args[0]

        if isinstance(weight_candidate, bool):
            raise WeightTypeException(weight_candidate)

        if not isinstance(weight_candidate, (int, float)):
            raise WeightTypeException(weight_candidate)

        if weight_candidate < MIN_VALID_WEIGHT or weight_candidate > MAX_VALID_WEIGHT:
            raise WeightValueException(weight_candidate)

        normalized_val = float(weight_candidate)
        new_args = (normalized_val,) + args[1:]
        return func(*new_args, **kwargs)
    return wrapper

@normalize_weight_input
def calculate_bmi(weight_kg, height_m=1.75):
    if height_m <= 0:
        raise ValueError("Height must be positive")
    return weight_kg / (height_m ** 2)

if __name__ == '__main__':
    valid_weight = 75
    try:
        bmi_result = calculate_bmi(valid_weight)
        print(bmi_result)
    except (WeightTypeException, WeightValueException) as e:
        print(e)

    invalid_negative_weight = -10
    try:
        calculate_bmi(invalid_negative_weight)
    except (WeightTypeException, WeightValueException) as e:
        print(e)

    invalid_type_weight = "sixty"
    try:
        calculate_bmi(invalid_type_weight)
    except (WeightTypeException, WeightValueException) as e:
        print(e)

    invalid_bool_weight = True
    try:
        calculate_bmi(invalid_bool_weight)
    except (WeightTypeException, WeightValueException) as e:
        print(e)

    invalid_large_weight = 2500.5
    try:
        calculate_bmi(invalid_large_weight)
    except (WeightTypeException, WeightValueException) as e:
        print(e)

import csv
import io

def calculate_average_weight(csv_content):
    weights = []
    reader = csv.reader(io.StringIO(csv_content))
    header_skipped = False
    for row in reader:
        if not row:
            continue
        if not header_skipped:
            try:
                float(row[0])
            except ValueError:
                header_skipped = True
                continue
            header_skipped = False
        for cell in row:
            cell = cell.strip()
            if not cell:
                continue
            try:
                weight = float(cell)
                weights.append(weight)
            except ValueError:
                continue
    if not weights:
        return 0.0
    return sum(weights) / len(weights)

if __name__ == '__main__':
    sample_csv_data = """weight
70.5
80.2
invalid
65.0
75.8
abc
90.1
"""
    average = calculate_average_weight(sample_csv_data)
    print(average)

from typing import List, Tuple

def compute_weighted_avg(data: List[Tuple[float, float]]) -> float:
    if not data:
        return 0.0
    numerator = 0.0
    denominator = 0.0
    for value, weight in data:
        numerator += value * weight
        denominator += weight
    if denominator == 0:
        return 0.0
    return numerator / denominator

if __name__ == '__main__':
    readings = [
        (100.0, 1),
        (150.0, 2),
        (200.0, 3)
    ]
    avg = compute_weighted_avg(readings)
    print(avg)

import functools

class WeightTypeError(Exception):
    def __init__(self, message):
        self.message = message
        super().__init__(self.message)

class ImpossibleWeightError(Exception):
    def __init__(self, message):
        self.message = message
        super().__init__(self.message)

MIN_WEIGHT = 0.0
MAX_WEIGHT = 500.0

def _extract_weight(args, kwargs):
    weight_index = 0
    if weight_index < len(args):
        return args[weight_index]
    if 'weight' in kwargs:
        return kwargs['weight']
    raise WeightTypeError("Missing weight argument")

def _validate_type(value):
    if isinstance(value, bool):
        raise WeightTypeError("Weight cannot be a boolean value")
    if not isinstance(value, (int, float)):
        raise WeightTypeError(f"Weight must be numeric, got {type(value).__name__}")

def _validate_value(value):
    if value < MIN_WEIGHT:
        raise ImpossibleWeightError(f"Weight {value} is negative")
    if value > MAX_WEIGHT:
        raise ImpossibleWeightError(f"Weight {value} exceeds maximum limit of {MAX_WEIGHT}")

def _normalize_value(value):
    return float(value)

def validate_weight(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        raw_weight = _extract_weight(args, kwargs)
        _validate_type(raw_weight)
        _validate_value(raw_weight)
        normalized_weight = _normalize_value(raw_weight)
        return func(normalized_weight)
    return wrapper

@validate_weight
def calculate_bmi(weight):
    height_m = 1.75
    return weight / (height_m * height_m)

@validate_weight
def get_weight_in_kg(weight):
    return weight

if __name__ == '__main__':
    valid_weight = 75.5
    bmi_result = calculate_bmi(valid_weight)
    print(f"BMI for {valid_weight}kg: {bmi_result:.2f}")

    kg_result = get_weight_in_kg(valid_weight)
    print(f"Weight in kg: {kg_result}")

    try:
        calculate_bmi(-10)
    except ImpossibleWeightError as e:
        print(f"Caught expected error: {e.message}")

    try:
        get_weight_in_kg("invalid")
    except WeightTypeError as e:
        print(f"Caught expected type error: {e.message}")

    try:
        calculate_bmi(True)
    except WeightTypeError as e:
        print(f"Caught expected bool error: {e.message}")

def normalize_weights(weights):
    if not weights:
        return []
    total = sum(weights)
    if total == 0:
        return [0.0] * len(weights)
    return [w / total for w in weights]

def compute_weighted_average(measurements, weights):
    if len(measurements) != len(weights):
        raise ValueError("Measurements and weights must have equal length")

    if not measurements:
        return 0.0

    normalized = normalize_weights(weights)

    weighted_sum = 0.0
    for value, weight in zip(measurements, normalized):
        weighted_sum += value * weight

    return weighted_sum

class WeightedDataProcessor:
    def __init__(self, measurements, weights):
        self.measurements = measurements
        self.weights = weights

    def get_average(self):
        return compute_weighted_average(self.measurements, self.weights)

if __name__ == '__main__':
    sample_measurements = [15.5, 22.0, 18.75, 30.2, 10.0]
    sample_weights = [2, 5, 1, 3, 4]

    processor = WeightedDataProcessor(sample_measurements, sample_weights)
    result = processor.get_average()
    print(result)

import functools

class WeightDataTypeError(TypeError):
    def __init__(self, value):
        self.value = value
        message = "Weight must be a numeric type, not {}.".format(type(value).__name__)
        super().__init__(message)

class WeightValueError(ValueError):
    def __init__(self, value, min_val, max_val):
        self.value = value
        self.min_val = min_val
        self.max_val = max_val
        message = "Weight value {} is out of range [{}, {}].".format(value, min_val, max_val)
        super().__init__(message)

MIN_WEIGHT = 0.0
MAX_WEIGHT = 1000.0

def _normalize_weight(value):
    if isinstance(value, bool):
        raise WeightDataTypeError(value)
    if not isinstance(value, (int, float)):
        raise WeightDataTypeError(value)
    normalized = float(value)
    if normalized < MIN_WEIGHT or normalized > MAX_WEIGHT:
        raise WeightValueError(normalized, MIN_WEIGHT, MAX_WEIGHT)
    return normalized

def weight_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if not args:
            raise WeightDataTypeError(None)
        weight_arg = args[0]
        validated_weight = _normalize_weight(weight_arg)
        new_args = (validated_weight,) + args[1:]
        return func(*new_args, **kwargs)
    return wrapper

@weight_decorator
def calculate_dosage(weight_kg):
    base_dose = 5.0
    dosage = base_dose * weight_kg * 1.1
    return round(dosage, 2)

@weight_decorator
def get_health_score(weight_kg):
    if weight_kg < 20:
        return "Underweight Risk"
    elif weight_kg > 150:
        return "Obesity Risk"
    return "Healthy Range"

if __name__ == '__main__':
    print(calculate_dosage(70))
    print(get_health_score(70))
    try:
        calculate_dosage(-5)
    except WeightValueError as e:
        print(e)
    try:
        get_health_score("heavy")
    except WeightDataTypeError as e:
        print(e)

import csv
import io
import tempfile
import os

class WeightAnalyzer:
    def __init__(self, file_path):
        self.file_path = file_path

    def load_and_clean_weights(self):
        weights = []
        with open(self.file_path, 'r', newline='', encoding='utf-8') as file:
            reader = csv.reader(file)
            for row in reader:
                for cell in row:
                    value = cell.strip()
                    if not value:
                        continue
                    try:
                        num = float(value)
                        weights.append(num)
                    except ValueError:
                        continue
        return weights

    def calculate_average(self):
        clean_weights = self.load_and_clean_weights()
        if not clean_weights:
            return 0.0
        return sum(clean_weights) / len(clean_weights)

def create_sample_csv():
    temp_file = tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.csv', encoding='utf-8')
    content = "weight,extra_column\n65.5,active\n70,rest\ninvalid,skip\n82.5,high\n45,low\n\n"
    temp_file.write(content)
    temp_file.close()
    return temp_file.name

if __name__ == '__main__':
    sample_path = create_sample_csv()
    try:
        analyzer = WeightAnalyzer(sample_path)
        result = analyzer.calculate_average()
        print(f"Average weight: {result}")
    finally:
        os.remove(sample_path)

import functools

class InvalidWeightTypeError(TypeError):
    def __init__(self, value):
        message = "Weight must be a number (int or float), not {}.".format(type(value).__name__)
        super().__init__(message)

class ImpossibleWeightValueError(ValueError):
    def __init__(self, value):
        message = "Weight value {} is impossible. It must be between 0.0 and 500.0 kg.".format(value)
        super().__init__(message)

MIN_WEIGHT_LIMIT = 0.0
MAX_WEIGHT_LIMIT = 500.0

def _check_weight_type(value):
    if isinstance(value, bool):
        return False
    if not isinstance(value, (int, float)):
        return False
    return True

def _check_weight_range(value):
    return MIN_WEIGHT_LIMIT < value <= MAX_WEIGHT_LIMIT

def weight_validator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        weight_arg = None
        if args:
            weight_arg = args[0]
        else:
            raise InvalidWeightTypeError("No weight argument provided")

        if not _check_weight_type(weight_arg):
            raise InvalidWeightTypeError(weight_arg)

        if not _check_weight_range(weight_arg):
            raise ImpossibleWeightValueError(weight_arg)

        normalized_weight = float(weight_arg)
        return func(normalized_weight, *args[1:], **kwargs)
    return wrapper

@weight_validator
def calculate_bmi(weight_kg, height_m):
    if height_m <= 0:
        raise ValueError("Height must be positive")
    return weight_kg / (height_m * height_m)

@weight_validator
def get_weight_category(weight_kg):
    if weight_kg < 50:
        return "Underweight"
    elif weight_kg < 80:
        return "Normal"
    elif weight_kw < 120:
        return "Overweight"
    else:
        return "Obese"

if __name__ == '__main__':
    valid_weights = [65, 70.5, 100, 0.1]
    invalid_weights = [-5, 600, "fifty", True, None]

    for w in valid_weights:
        try:
            bmi = calculate_bmi(w, 1.75)
            print("Weight: {} kg -> BMI: {:.2f}".format(w, bmi))
        except Exception as e:
            print("Error for weight {}: {}".format(w, e))

    for w in invalid_weights:
        try:
            result = calculate_bmi(w, 1.75)
            print("Unexpected success for {}: {}".format(w, result))
        except (InvalidWeightTypeError, ImpossibleWeightValueError) as e:
            print("Correctly caught error for {}: {}".format(w, e))

    test_cat_weight = 120
    try:
        cat = get_weight_category(test_cat_weight)
        print("Weight {} category: {}".format(test_cat_weight, cat))
    except Exception as e:
        print("Error calculating category for {}: {}".format(test_cat_weight, e))

from typing import List, Tuple

class WeightedMeasurementProcessor:
    def __init__(self, data: List[Tuple[float, float]]):
        self.data = data

    def calculate(self) -> float:
        if not self.data:
            return 0.0
        weighted_sum = 0.0
        weight_accumulator = 0.0
        for value, weight in self.data:
            if weight < 0:
                raise ValueError("Weights cannot be negative")
            weighted_sum += value * weight
            weight_accumulator += weight
        if weight_accumulator == 0:
            return 0.0
        return weighted_sum / weight_accumulator

if __name__ == '__main__':
    sample_measurements = [
        (15.5, 1),
        (20.0, 2),
        (25.5, 3),
        (10.0, 4)
    ]
    processor = WeightedMeasurementProcessor(sample_measurements)
    result = processor.calculate()
    print(result)

