class WeightedMeasurementCalculator:
    def __init__(self, measurements):
        self.measurements = measurements

    def compute(self):
        weighted_sum = 0.0
        total_weight = 0.0
        for value, weight in self.measurements:
            weighted_sum += value * weight
            total_weight += weight
        if total_weight == 0:
            return 0.0
        return weighted_sum / total_weight

