import csv
import io

def calculate_average_weight(csv_content):
    weights = []
    csv_file = io.StringIO(csv_content)
    reader = csv.reader(csv_file)
    for row in reader:
        if not row:
            continue
        for value in row:
            stripped = value.strip()
            if not stripped:
                continue
            try:
                weight = float(stripped)
                weights.append(weight)
            except ValueError:
                continue
    if not weights:
        return 0.0
    return sum(weights) / len(weights)

