    manager.store("box_a", 10.5)
    manager.store("box_b", 20.0)
    new_val = manager.add("box_a", 5.5)
    print(new_val)
    current = manager.get("box_b")
    print(current)
    all_vals = manager.get_all()
    print(all_vals)
    removed = manager.remove("box_a")
    print(removed)
    final_vals = manager.get_all()
    print(final_vals)

