import numpy as np

def scale_volumes(volumes, factor):
    return volumes * factor

def calculate_statistics(volumes):
    if volumes.size == 0:
        return {
            'mean': 0.0,
            'std': 0.0,
            'min': 0.0,
            'max': 0.0
        }
    return {
        'mean': np.mean(volumes),
        'std': np.std(volumes),
        'min': np.min(volumes),
        'max': np.max(volumes)
    }

def apply_threshold(volumes, threshold):
    return volumes[volumes > threshold]

def normalize_volumes(volumes):
    min_val = np.min(volumes)
    max_val = np.max(volumes)
    if max_val == min_val:
        return np.zeros_like(volumes)
    return (volumes - min_val) / (max_val - min_val)

def process_volumes(volumes, scale_factor, threshold):
    scaled = scale_volumes(volumes, scale_factor)
    stats = calculate_statistics(scaled)
    filtered = apply_threshold(scaled, threshold)
    normalized = normalize_volumes(scaled)
    return {
        'scaled': scaled,
        'statistics': stats,
        'filtered_count': filtered.shape[0],
        'normalized': normalized
    }

if __name__ == '__main__':
    volumes_data = np.array([10.5, 20.0, 30.5, 40.0, 50.5, 60.0, 70.5, 80.0, 90.5, 100.0])
    result = process_volumes(volumes_data, 2.0, 50.0)
    print(result['scaled'])
    print(result['statistics'])
    print(result['filtered_count'])
    print(result['normalized'])

import numpy as np

class VolumeCalculator:
    def __init__(self, volumes):
        self.volumes = np.array(volumes, dtype=np.float64)

    def scale_volumes(self, factor):
        return self.volumes * factor

    def convert_units(self, from_unit='cubic_meters', to_unit='liters'):
        conversion_factors = {
            ('cubic_meters', 'liters'): 1000.0,
            ('liters', 'cubic_meters'): 0.001,
            ('cubic_meters', 'gallons'): 264.172,
            ('gallons', 'cubic_meters'): 1 / 264.172,
            ('liters', 'gallons'): 0.264172,
            ('gallons', 'liters'): 3.78541,
        }
        if from_unit == to_unit:
            return self.volumes.copy()
        factor = conversion_factors.get((from_unit, to_unit))
        if factor is None:
            raise ValueError(f"Unsupported conversion from {from_unit} to {to_unit}")
        return self.volumes * factor

    def aggregate_statistics(self):
        mean_val = np.mean(self.volumes)
        median_val = np.median(self.volumes)
        std_val = np.std(self.volumes)
        total_val = np.sum(self.volumes)
        return {
            'mean': mean_val,
            'median': median_val,
            'std': std_val,
            'total': total_val
        }

def process_volume_data():
    sample_volumes = [1.5, 2.3, 0.75, 4.0, 1.1, 3.3, 2.8, 0.9]
    calculator = VolumeCalculator(sample_volumes)
    scaled_volumes = calculator.scale_volumes(2.5)
    converted_volumes = calculator.convert_units(from_unit='cubic_meters', to_unit='liters')
    stats = calculator.aggregate_statistics()
    return {
        'original': sample_volumes,
        'scaled': scaled_volumes.tolist(),
        'converted': converted_volumes.tolist(),
        'statistics': stats
    }

if __name__ == '__main__':
    result = process_volume_data()
    print(result)

import numpy as np

class VolumeScaler:
    def __init__(self, unit_multiplier):
        self.unit_multiplier = unit_multiplier

    def scale_volumes(self, measurements):
        input_array = np.array(measurements, dtype=np.float64)
        if input_array.size == 0:
            return np.array([], dtype=np.float64)
        return input_array * self.unit_multiplier

    def calculate_total_volume(self, measurements):
        input_array = np.array(measurements, dtype=np.float64)
        if input_array.size == 0:
            return 0.0
        return np.sum(input_array)

