import os
import tempfile

def calculate_total_volume(file_path):
    total = 0.0
    try:
        with open(file_path, 'r') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    value = float(line)
                    total += value
                except ValueError:
                    continue
        return total
    except FileNotFoundError:
        return 0.0
    except IOError:
        return 0.0

