import unittest
import math

def volume_cylinder(radius, height):
    if radius < 0 or height < 0:
        raise ValueError("Radius and height must be non-negative")
    return math.pi * (radius ** 2) * height

def volume_sphere(radius):
    if radius < 0:
        raise ValueError("Radius must be non-negative")
    return (4/3) * math.pi * (radius ** 3)

def volume_cone(radius, height):
    if radius < 0 or height < 0:
        raise ValueError("Radius and height must be non-negative")
    return (1/3) * math.pi * (radius ** 2) * height

class TestVolumeCalculations(unittest.TestCase):
    def test_cylinder_positive_values(self):
        result = volume_cylinder(1, 1)
        expected = math.pi
        self.assertAlmostEqual(result, expected)

    def test_cylinder_zero_radius(self):
        result = volume_cylinder(0, 5)
        self.assertEqual(result, 0)

    def test_cylinder_zero_height(self):
        result = volume_cylinder(3, 0)
        self.assertEqual(result, 0)

    def test_cylinder_negative_radius(self):
        with self.assertRaises(ValueError):
            volume_cylinder(-1, 5)

    def test_cylinder_negative_height(self):
        with self.assertRaises(ValueError):
            volume_cylinder(1, -5)

    def test_cylinder_negative_both(self):
        with self.assertRaises(ValueError):
            volume_cylinder(-1, -5)

    def test_sphere_positive_value(self):
        result = volume_sphere(1)
        expected = (4/3) * math.pi
        self.assertAlmostEqual(result, expected)

    def test_sphere_zero_radius(self):
        result = volume_sphere(0)
        self.assertEqual(result, 0)

    def test_sphere_negative_radius(self):
        with self.assertRaises(ValueError):
            volume_sphere(-1)

    def test_cone_positive_values(self):
        result = volume_cone(1, 1)
        expected = math.pi / 3
        self.assertAlmostEqual(result, expected)

    def test_cone_zero_radius(self):
        result = volume_cone(0, 10)
        self.assertEqual(result, 0)

    def test_cone_zero_height(self):
        result = volume_cone(5, 0)
        self.assertEqual(result, 0)

    def test_cone_negative_radius(self):
        with self.assertRaises(ValueError):
            volume_cone(-1, 5)

    def test_cone_negative_height(self):
        with self.assertRaises(ValueError):
            volume_cone(5, -5)

    def test_cone_negative_both(self):
        with self.assertRaises(ValueError):
            volume_cone(-1, -5)

if __name__ == '__main__':
    res_cyl = volume_cylinder(2, 3)
    res_sph = volume_sphere(3)
    res_cone = volume_cone(4, 5)
    print(res_cyl)
    print(res_sph)
    print(res_cone)
    unittest.main()

import unittest
import math

def calculate_volume(length, width, height):
    if length <= 0 or width <= 0 or height <= 0:
        raise ValueError("Dimensions must be positive")
    return length * width * height

def calculate_sphere_volume(radius):
    if radius <= 0:
        raise ValueError("Radius must be positive")
    return (4.0 / 3.0) * math.pi * (radius ** 3)

class TestVolumeCalculations(unittest.TestCase):
    def test_normal_cuboid_volume(self):
        result = calculate_volume(2, 3, 4)
        self.assertEqual(result, 24)

    def test_zero_length_cuboid(self):
        with self.assertRaises(ValueError):
            calculate_volume(0, 3, 4)

    def test_negative_length_cuboid(self):
        with self.assertRaises(ValueError):
            calculate_volume(-1, 3, 4)

    def test_zero_width_cuboid(self):
        with self.assertRaises(ValueError):
            calculate_volume(2, 0, 4)

    def test_negative_width_cuboid(self):
        with self.assertRaises(ValueError):
            calculate_volume(2, -1, 4)

    def test_zero_height_cuboid(self):
        with self.assertRaises(ValueError):
            calculate_volume(2, 3, 0)

    def test_negative_height_cuboid(self):
        with self.assertRaises(ValueError):
            calculate_volume(2, 3, -1)

    def test_normal_sphere_volume(self):
        result = calculate_sphere_volume(3)
        expected = (4.0 / 3.0) * math.pi * 27
        self.assertAlmostEqual(result, expected)

    def test_zero_radius_sphere(self):
        with self.assertRaises(ValueError):
            calculate_sphere_volume(0)

    def test_negative_radius_sphere(self):
        with self.assertRaises(ValueError):
            calculate_sphere_volume(-1)

if __name__ == '__main__':
    print(calculate_volume(5, 10, 2))
    try:
        calculate_volume(0, 5, 5)
    except ValueError as e:
        print(e)
    try:
        calculate_sphere_volume(-5)
    except ValueError as e:
        print(e)
    print(calculate_sphere_volume(1))
    unittest.main()

import os
import tempfile

def calculate_total_volume(volume_strings):
    total = 0.0
    for s in volume_strings:
        try:
            total += float(s)
        except (ValueError, TypeError):
            continue
    return total

def read_volumes_from_file(filepath):
    volumes = []
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if line:
                volumes.append(line)
    return volumes

def main():
    sample_lines = ["1.5", "2.3", "invalid", "0.2", "", "3"]
    with tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.txt') as tmp:
        for line in sample_lines:
            tmp.write(line + '\n')
        tmp_path = tmp.name

    try:
        volumes = read_volumes_from_file(tmp_path)
        result = calculate_total_volume(volumes)
        print(result)
    finally:
        os.unlink(tmp_path)

if __name__ == '__main__':
    main()

