def read_volumes_from_file(file_path):
    volumes = []
    with open(file_path, 'r') as f:
        for line in f:
            stripped = line.strip()
            if stripped:
                try:
                    volumes.append(float(stripped))
                except ValueError:
                    continue
    return volumes

def calculate_total_volume(file_path):
    volumes = read_volumes_from_file(file_path)
    return sum(volumes)

def write_temp_file():
    import tempfile
