        'liters': 0.001,
        'milliliters': 0.000001,
        'gallons': 0.00378541,
        'cubic_feet': 0.0283168,
        'cubic_inches': 0.0000163871,
        'imperial_gallons': 0.00454609,
        'barrels': 0.158987,
        'fluid_ounces': 0.0000295735,
