    print(v1.equals(v2))
    print(v1.equals(v3))

import math
import struct

class VolumeStore:
    def __init__(self):
        self._data = {}

    def set(self, key, value):
        if not isinstance(key, tuple):
            raise TypeError("Key must be a tuple of coordinates.")
        if not isinstance(value, (int, float)):
            raise TypeError("Value must be numeric.")
        self._data[key] = float(value)

    def get(self, key):
        if not isinstance(key, tuple):
            raise TypeError("Key must be a tuple of coordinates.")
        return self._data.get(key, 0.0)

    def scale(self, factor):
        if not isinstance(factor, (int, float)):
            raise TypeError("Factor must be numeric.")
        if factor == 0:
            self._data.clear()
            return

        new_data = {}
        for key, value in self._data.items():
            new_key = tuple(math.floor(coord * factor) for coord in key)
            new_data[new_key] = value

        self._data = new_data

    def get_total_volume(self):
        return sum(self._data.values())

    def get_max_key(self):
        if not self._data:
            return None
        return max(self._data.keys())

    def get_min_key(self):
        if not self.data:
            return None
        return min(self._data.keys())

if __name__ == '__main__':
    store = VolumeStore()

    store.set((1, 2, 3), 10.0)
    store.set((4, 5, 6), 20.0)
    store.set((2, 2, 2), 5.0)

    total = store.get_total_volume()
    print(total)

    max_key = store.get_max_key()
    print(max_key)

    scale_factor = 2
    store.scale(scale_factor)

    new_val = store.get((2, 4, 6))
    print(new_val)

    new_total = store.get_total_volume()
    print(new_total)

    new_max_key = store.get_max_key()
    print(new_max_key)

import math

class VolumeMeasurement:
    CONVERSION_TO_CC = {
        'liters': 1000.0,
        'milliliters': 1.0,
        'gallons': 3785.411784,
        'cubic_meters': 1000000.0,
        'cubic_centimeters': 1.0
    }

    def __init__(self, value, unit='cubic_centimeters'):
        if unit not in self.CONVERSION_TO_CC:
            raise ValueError(f"Unit {unit} is not supported")
        self._base_cc = float(value) * self.CONVERSION_TO_CC[unit]

    @property
    def cubic_centimeters(self):
        return self._base_cc

    def to_liters(self):
        return self._base_cc / self.CONVERSION_TO_CC['liters']

    def to_milliliters(self):
        return self._base_cc / self.CONVERSION_TO_CC['milliliters']

    def to_gallons(self):
        return self._base_cc / self.CONVERSION_TO_CC['gallons']

    def to_cubic_meters(self):
        return self._base_cc / self.CONVERSION_TO_CC['cubic_meters']

    def __add__(self, other):
        if isinstance(other, VolumeMeasurement):
            return VolumeMeasurement(self._base_cc + other._base_cc, 'cubic_centimeters')
        return NotImplemented

    def __sub__(self, other):
        if isinstance(other, VolumeMeasurement):
            return VolumeMeasurement(self._base_cc - other._base_cc, 'cubic_centimeters')
        return NotImplemented

    def __mul__(self, scalar):
        return VolumeMeasurement(self._base_cc * float(scalar), 'cubic_centimeters')

    def __rmul__(self, scalar):
        return self.__mul__(scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            raise ZeroDivisionError("Cannot divide volume by zero")
        return VolumeMeasurement(self._base_cc / float(scalar), 'cubic_centimeters')

    def __eq__(self, other):
        if not isinstance(other, VolumeMeasurement):
            return False
        return math.isclose(self._base_cc, other._base_cc, rel_tol=1e-9)

    def __repr__(self):
        return f"VolumeMeasurement({self._base_cc} cc)"

if __name__ == '__main__':
    v1 = VolumeMeasurement(1, 'liters')
    v2 = VolumeMeasurement(500, 'milliliters')

    print(v1.to_liters())
    print(v1.to_milliliters())
    print(v1.to_gallons())
    print(v1.to_cubic_meters())

    print(v2.to_liters())
    print(v2.to_milliliters())
    print(v2.to_gallons())
    print(v2.to_cubic_meters())

    v3 = v1 + v2
    print(v3.to_liters())

    v4 = v1 - v2
    print(v4.to_milliliters())

    v5 = v1 * 2
    print(v5.to_liters())

    v6 = v1 / 2
    print(v6.to_milliliters())

    print(v1 == VolumeMeasurement(1000, 'cubic_centimeters'))

class VolumeStore:
    def __init__(self, base_unit_factor=1.0):
        self._base_factor = float(base_unit_factor)
        self._volume = 0.0

    def add_measurement(self, value, unit_factor=1.0):
        adjusted_value = value * unit_factor
        self._volume += adjusted_value

    def get_current_volume(self, scale_factor=1.0):
        if scale_factor == 0:
            return 0.0
        return self._volume * self._base_factor * scale_factor

    def set_base_unit(self, factor):
        self._base_factor = float(factor)

    def reset(self):
        self._volume = 0.0

