    volume.set(0, 0, 0, 10.0)
    volume.set(1, 1, 1, 20.0)
    volume.set(10, 10, 10, 5.0)
    volume.set_scale(10.0)
    val_at_5_5_5 = volume.get_scaled_value(5, 5, 5)
    print(val_at_5_5_5)
    total_in_range = volume.get_range_sum(0, 15, 0, 15, 0, 15)
    print(total_in_range)

