        unit_lower = unit.lower()
        if unit_lower in conversion_factors:
            converted = value * conversion_factors[unit_lower]
            if converted < 0:
                results.append(0.0)
            else:
                results.append(converted)
        else:
            results.append(0.0)

    return results

