    sample_path = create_sample_csv()
    try:
        result = calculate_average_temperature(sample_path)
        print(result)
    finally:
        if os.path.exists(sample_path):
            os.remove(sample_path)

def convert_to_milliliters(volumes):
    ml_per_unit = {
        'liters': 1000.0,
        'gallons': 3785.411784,
        'cubic_inches': 16.387064
    }
    result = []
    for volume, unit in volumes:
        if unit not in ml_per_unit:
            raise ValueError(f"Unsupported unit: {unit}")
        if volume == 0:
            result.append(0.0)
        elif volume < 0:
            result.append(-abs(volume) * ml_per_unit[unit])
        else:
            result.append(volume * ml_per_unit[unit])
    return result

