import argparse
import json
import sys
from typing import List, Union

def convert_celsius_to_fahrenheit(celsius: Union[int, float]) -> float:
    return celsius * 9.0 / 5.0 + 32.0

def batch_convert_temperatures(
    input_data: List[Union[int, float]],
) -> List[float]:
    return [convert_celsius_to_fahrenheit(temp) for temp in input_data]

def load_temperature_data(file_path: str) -> List[Union[int, float]]:
    try:
        with open(file_path, "r") as f:
            data = json.load(f)
        if not isinstance(data, list):
            raise ValueError("Input data must be a JSON array of numbers")
        for item in data:
            if not isinstance(item, (int, float)):
                raise ValueError("All elements must be numeric")
        return data
    except FileNotFoundError:
        raise FileNotFoundError(f"The file '{file_path}' was not found.")
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON format in '{file_path}': {e}")

def create_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Batch convert temperature data from Celsius to Fahrenheit."
    )
    parser.add_argument(
        "input_file",
        type=str,
        help="Path to the input JSON file containing an array of Celsius temperatures.",
    )
    parser.add_argument(
        "--output",
        type=str,
        default=None,
        help="Optional path to write the converted Fahrenheit values as JSON.",
    )
    return parser

def main(args=None):
    if args is None:
        args = []

    parser = create_parser()

    parsed_args = parser.parse_args(args)

    celsius_data = load_temperature_data(parsed_args.input_file)
    fahrenheit_data = batch_convert_temperatures(celsius_data)

    if parsed_args.output:
        try:
            with open(parsed_args.output, "w") as f:
                json.dump(fahrenheit_data, f)
        except IOError as e:
            raise IOError(f"Failed to write to output file '{parsed_args.output}': {e}")

    return fahrenheit_data

if __name__ == '__main__':
    import tempfile
    import os

    sample_celsius_data = [0, 100, 37, -40, 25.5]

    with tempfile.NamedTemporaryFile(mode="w", suffix=".json", delete=False) as tmp:
        json.dump(sample_celsius_data, tmp)
        temp_file_path = tmp.name

    try:
        result = main([temp_file_path])
        print(result)
    finally:
        os.unlink(temp_file_path)

import argparse
import sys
import os
import tempfile
import json
import math

def convert_celsius_to_fahrenheit(celsius_value):
    return celsius_value * 9 / 5 + 32

def process_temperature_file(input_path, output_path):
    if not os.path.exists(input_path):
        raise FileNotFoundError(f"Input file not found: {input_path}")

    try:
        with open(input_path, 'r', encoding='utf-8') as infile:
            lines = infile.readlines()
    except Exception as e:
        raise IOError(f"Error reading input file: {e}")

    if not lines:
        raise ValueError("Input file is empty")

    results = []
    for line_num, line in enumerate(lines, 1):
        line = line.strip()
        if not line:
            continue

        try:
            value = float(line)
            if math.isnan(value) or math.isinf(value):
                raise ValueError(f"Invalid numeric value at line {line_num}")
            converted = convert_celsius_to_fahrenheit(value)
            results.append({
                "original": value,
                "converted": converted,
                "line": line_num
            })
        except ValueError:
            raise ValueError(f"Invalid temperature value at line {line_num}: {line}")

    if not results:
        raise ValueError("No valid temperature data found in input file")

    try:
        with open(output_path, 'w', encoding='utf-8') as outfile:
            for result in results:
                outfile.write(f"{result['converted']:.2f}\n")
    except Exception as e:
        raise IOError(f"Error writing output file: {e}")

    return results

def main():
    parser = argparse.ArgumentParser(description='Batch convert temperature data from Celsius to Fahrenheit')
    parser.add_argument('--input', required=False, help='Input file path containing Celsius values')
    parser.add_argument('--output', required=False, help='Output file path for Fahrenheit values')

    args = parser.parse_args()

    if args.input is None or args.output is None:
        temp_input = tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.txt')
        temp_input.write("0\n100\n37.5\n-273.15\n")
        temp_input.close()

        temp_output = tempfile.NamedTemporaryFile(delete=False, suffix='.txt')
        temp_output.close()

        input_path = temp_input.name
        output_path = temp_output.name
    else:
        input_path = args.input
        output_path = args.output

    if not os.path.exists(input_path):
        temp_input = tempfile.NamedTemporaryFile(mode='w', delete=False, suffix='.txt')
        temp_input.write("0\n100\n37.5\n-273.15\n")
        temp_input.close()
        input_path = temp_input.name

    try:
        results = process_temperature_file(input_path, output_path)
        print(json.dumps(results, indent=2))
    finally:
        if 'temp_input' in locals() and os.path.exists(input_path):
            os.remove(input_path)
        if 'temp_output' in locals() and os.path.exists(output_path):
            os.remove(output_path)

if __name__ == '__main__':
    main()

