    conversions_to_meters = {
        'meters': 1.0,
        'kilometers': 1000.0,
        'miles': 1609.34
    }
    value_in_meters = value * conversions_to_meters[from_unit]
    result = value_in_meters / conversions_to_meters[to_unit]
    return result

