    if abs(meters) < 1e-15:
        return 0.0
    if target_unit == 'km':
        result = meters / 1000.0
    elif target_unit == 'm':
        result = meters
    elif target_unit == 'cm':
        result = meters * 100.0
    elif target_unit == 'mm':
        result = meters * 1000.0
    elif target_unit == 'mi':
        result = meters / 1609.344
    elif target_unit == 'ft':
        result = meters / 3.28084
    elif target_unit == 'in':
