    if not list_a and not list_b:
        return {"max_length": None, "min_length": None, "range_difference": 0}

    combined_list = list_a + list_b

    if not combined_list:
        return {"max_length": None, "min_length": None, "range_difference": 0}

    max_len = max(combined_list)
    min_len = min(combined_list)
