class ImpossibleLengthError(Exception):
    def __init__(self, message):
        Exception.__init__(self, message)
        self.message = message

class LengthComparator:
    def __init__(self, length_a, length_b):
        self.length_a = length_a
        self.length_b = length_b

    def compare(self):
        if self.length_a < 0 or self.length_b < 0:
            raise ImpossibleLengthError("Length cannot be negative")
        if self.length_a > self.length_b:
            return self.length_a - self.length_b
        return self.length_b - self.length_a

if __name__ == '__main__':
    try:
        comparator = LengthComparator(10, 5)
        result = comparator.compare()
        print(result)
    except ImpossibleLengthError:
        print("Caught exception")
    try:
        comparator_invalid = LengthComparator(-5, 5)
        result_invalid = comparator_invalid.compare()
        print(result_invalid)
    except ImpossibleLengthError:
        print("Caught exception for invalid input")

NEGATIVE_LENGTH_MSG = "Length cannot be negative"

class ImpossibleLengthError(Exception):
    def __init__(self, msg):
        Exception.__init__(self, msg)
        self.msg_value = msg

class LengthHolder:
    def __init__(self, first_len, second_len):
        self.first_len = first_len
        self.second_len = second_len

    def validate_and_compare(self):
        if self.first_len < 0:
            raise ImpossibleLengthError(NEGATIVE_LENGTH_MSG)
        if self.second_len < 0:
            raise ImpossibleLengthError(NEGATIVE_LENGTH_MSG)
        diff = abs(self.first_len - self.second_len)
        return diff

def run_comparison(a_val, b_val):
    holder = LengthHolder(a_val, b_val)
    return holder.validate_and_compare()

if __name__ == '__main__':
    try:
        result = run_comparison(10, 5)
        print(result)
    except ImpossibleLengthError as e:
        print(e.msg_value)

def compare_lengths(seq1, seq2):
    it1 = iter(seq1)
    it2 = iter(seq2)
    while True:
        try:
            next(it1)
        except StopIteration:
            len1_done = True
            break
    else:
        len1_done = False

    while True:
        try:
            next(it2)
        except StopIteration:
            len2_done = True
            break
    else:
        len2_done = False

    if len1_done and len2_done:
        return "equal"
    elif len1_done:
        return "second longer"
    elif len2_done:
        return "first longer"
    else:
        return "both ongoing"

