        self.value = value
        self.unit = unit

    def __eq__(self, other):
        if not isinstance(other, Measurement):
            return False
        return self.value == other.value and self.unit == other.unit

    def __repr__(self):
        return f"Measurement({self.value}, '{self.unit}')"

class LengthComparator:
