        self._store = {}

    def add_pair(self, id1, id2, w1, w2):
        key = (id1, id2)
        self._store[key] = (w1, w2)

    def get_difference(self, id1, id2):
        key = (id1, id2)
        if key in self._store:
            w1, w2 = self._store[key]
            return w1 - w2
