import math

def _normalize_weight(value):
    if isinstance(value, int):
        return float(value)
    return float(value)

def calculate_weight_difference(weight1, weight2):
    n1 = _normalize_weight(weight1)
    n2 = _normalize_weight(weight2)
    if n1 >= n2:
        return n1 - n2
    return n2 - n1

