def convert_time(value, source_unit, target_unit):
    source_unit = source_unit.lower()
    target_unit = target_unit.lower()

    if source_unit not in ('seconds', 'minutes', 'hours') or target_unit not in ('seconds', 'minutes', 'hours'):
        raise ValueError("Invalid unit. Use 'seconds', 'minutes', or 'hours'.")

    if source_unit == target_unit:
        return value

    value_in_seconds = 0
    if source_unit == 'seconds':
        value_in_seconds = value
    elif source_unit == 'minutes':
        value_in_seconds = value * 60
    elif source_unit == 'hours':
        value_in_seconds = value * 3600

    if target_unit == 'seconds':
        return value_in_seconds
    elif target_unit == 'minutes':
        return value_in_seconds / 60
    elif target_unit == 'hours':
        return value_in_seconds / 3600

if __name__ == '__main__':
    result1 = convert_time(1, 'hours', 'minutes')
    result2 = convert_time(90, 'minutes', 'hours')
    result3 = convert_time(3600, 'seconds', 'hours')
    print(result1)
    print(result2)
    print(result3)

def convert_time(value, source_unit, target_unit):
    units_to_seconds = {
        'seconds': 1,
        'minutes': 60,
        'hours': 3600
    }

    if source_unit not in units_to_seconds or target_unit not in units_to_seconds:
        raise ValueError("Invalid unit. Use 'seconds', 'minutes', or 'hours'.")

    if value < 0:
        raise ValueError("Time value cannot be negative.")

    seconds = value * units_to_seconds[source_unit]
    result = seconds / units_to_seconds[target_unit]

    return result

if __name__ == '__main__':
    result1 = convert_time(1, 'hours', 'minutes')
    print(result1)

    result2 = convert_time(90, 'minutes', 'seconds')
    print(result2)

    result3 = convert_time(3600, 'seconds', 'hours')
    print(result3)

def convert_time(value, source_unit, target_unit):
    if source_unit == target_unit:
        return value

    units_to_seconds = {
        'seconds': 1,
        'minutes': 60,
        'hours': 3600
    }

    if source_unit not in units_to_seconds or target_unit not in units_to_seconds:
        raise ValueError("Unsupported unit. Choose from 'seconds', 'minutes', 'hours'.")

    seconds = value * units_to_seconds[source_unit]

    return seconds / units_to_seconds[target_unit]

if __name__ == '__main__':
    result = convert_time(2, 'hours', 'minutes')
    print(result)

class WeightMetric:
    def __init__(self, value):
        if not isinstance(value, (int, float)):
            raise TypeError("Weight must be a numeric type")
        if value < 0:
            raise ValueError("Weight cannot be negative")
        self.value = value

    def get_value(self):
        return self.value

def compute_weight_difference(w1, w2):
    metric1 = WeightMetric(w1)
    metric2 = WeightMetric(w2)
    val1 = metric1.get_value()
    val2 = metric2.get_value()
    diff = val1 - val2
    return abs(diff)

if __name__ == '__main__':
    initial = 200.0
    final = 175.5
    result = compute_weight_difference(initial, final)
    print(result)

def convert_time(value, source_unit, target_unit):
    units = {'seconds': 1, 'minutes': 60, 'hours': 3600}
    if source_unit not in units or target_unit not in units:
        raise ValueError(f"Invalid unit: {source_unit if source_unit not in units else target_unit}")

    seconds = value * units[source_unit]
    return seconds / units[target_unit]

if __name__ == '__main__':
    result1 = convert_time(60, 'seconds', 'minutes')
    result2 = convert_time(2, 'hours', 'minutes')
    result3 = convert_time(90, 'minutes', 'hours')
    print(result1)
    print(result2)
    print(result3)

