class Rectangle:
    def __init__(self, width, height):
        self._width = self._validate_dimension(width, "width")
        self._height = self._validate_dimension(height, "height")

    @staticmethod
    def _validate_dimension(value, name):
        if not isinstance(value, (int, float)):
            raise TypeError(f"The {name} must be a numeric value.")
        if value < 0:
            raise ValueError(f"The {name} cannot be negative.")
        return float(value)

    def get_area(self):
        return self._width * self._height

    def get_perimeter(self):
        return 2 * (self._width + self._height)

if __name__ == '__main__':
    sample_width = 12.5
    sample_height = 7.2
    rect = Rectangle(sample_width, sample_height)
    calculated_area = rect.get_area()
    print(calculated_area)

import numpy as np

def smallest_bounding_box_area(coordinates):
    if not coordinates:
        return 0.0
    points = np.array(coordinates)
    if points.ndim == 1:
        points = points.reshape(1, -1)
    x_coords = points[:, 0]
    y_coords = points[:, 1]
    width = np.max(x_coords) - np.min(x_coords)
    height = np.max(y_coords) - np.min(y_coords)
    return float(width * height)

if __name__ == '__main__':
    sample_coords = [(0, 0), (3, 0), (3, 4), (0, 4)]
    area = smallest_bounding_box_area(sample_coords)
    print(area)

