import numpy as np

def calculate_bounding_box_area(coordinates):
    if not coordinates:
        return 0.0
    points = np.array(coordinates)
    min_coords = np.min(points, axis=0)
    max_coords = np.max(points, axis=0)
    if np.any(min_coords == max_coords):
        return 0.0
    widths = max_coords - min_coords
    return float(np.prod(widths))

if __name__ == '__main__':
    sample_coordinates = [(1, 2), (3, 5), (6, 8), (4, 3)]
    result = calculate_bounding_box_area(sample_coordinates)
    print(result)

import numpy as np

def calculate_bounding_box_area(coordinates):
    if not coordinates:
        return 0.0
    points = np.array(coordinates)
    if points.ndim != 2 or points.shape[1] < 2:
        raise ValueError("Coordinates must be a list of (x, y) tuples")
    min_x, min_y = np.min(points, axis=0)
    max_x, max_y = np.max(points, axis=0)
    width = max_x - min_x
    height = max_y - min_y
    return float(width * height)

if __name__ == '__main__':
    sample_coordinates = [(1, 1), (5, 2), (3, 4), (4, 1)]
    area = calculate_bounding_box_area(sample_coordinates)
    print(area)

