import math

CONVERSION_FACTORS = {
    'liter': 1.0,
    'milliliter': 0.001,
    'cubic_meter': 1000.0,
    'gallon': 3.78541,
    'cubic_inch': 0.0163871,
}

UNIT_LABELS = {
    'liter': 'Liters',
    'milliliter': 'Milliliters',
    'cubic_meter': 'Cubic Meters',
    'gallon': 'Gallons',
    'cubic_inch': 'Cubic Inches',
}

def convert_volume(value, from_unit, to_unit):
    if from_unit not in CONVERSION_FACTORS:
        raise ValueError(f"Unknown source unit: {from_unit}")
    if to_unit not in CONVERSION_FACTORS:
        raise ValueError(f"Unknown target unit: {to_unit}")

    value_in_liters = value * CONVERSION_FACTORS[from_unit]
    converted_value = value_in_liters / CONVERSION_FACTORS[to_unit]
    return converted_value

def print_conversions(value, from_unit):
    results = {}
    for unit in CONVERSION_FACTORS:
        if unit == from_unit:
            results[unit] = value
        else:
            results[unit] = convert_volume(value, from_unit, unit)
    return results

if __name__ == '__main__':
    sample_value = 1.5
    sample_unit = 'gallon'

    converted_values = print_conversions(sample_value, sample_unit)

    for unit, val in converted_values.items():
        print(f"{UNIT_LABELS[unit]}: {val:.6f}")

def liters_to_milliliters(liters):
    return liters * 1000

def liters_to_cubic_meters(liters):
    return liters / 1000

def liters_to_gallons(liters):
    return liters * 0.264172

def liters_to_cubic_inches(liters):
    return liters * 61.0237

def milliliters_to_liters(milliliters):
    return milliliters / 1000

def cubic_meters_to_liters(cubic_meters):
    return cubic_meters * 1000

def gallons_to_liters(gallons):
    return gallons / 0.264172

def cubic_inches_to_liters(cubic_inches):
    return cubic_inches / 61.0237

def convert_volume(value, from_unit, to_unit):
    liters = 0.0
    if from_unit == "ml":
        liters = milliliters_to_liters(value)
    elif from_unit == "m3":
        liters = cubic_meters_to_liters(value)
    elif from_unit == "gal":
        liters = gallons_to_liters(value)
    elif from_unit == "in3":
        liters = cubic_inches_to_liters(value)
    elif from_unit == "l":
        liters = value
    else:
        raise ValueError("Unsupported source unit")

    if to_unit == "ml":
        return liters_to_milliliters(liters)
    elif to_unit == "m3":
        return liters_to_cubic_meters(liters)
    elif to_unit == "gal":
        return liters_to_gallons(liters)
    elif to_unit == "in3":
        return liters_to_cubic_inches(liters)
    elif to_unit == "l":
        return liters
    else:
        raise ValueError("Unsupported target unit")

if __name__ == '__main__':
    sample_value = 5.0
    sample_from = "l"
    sample_to = "gal"
    result = convert_volume(sample_value, sample_from, sample_to)
    print(result)
    sample_value_two = 1000
    sample_from_two = "ml"
    sample_to_two = "l"
    result_two = convert_volume(sample_value_two, sample_from_two, sample_to_two)
    print(result_two)
    sample_value_three = 1
    sample_from_three = "m3"
    sample_to_three = "in3"
    result_three = convert_volume(sample_value_three, sample_from_three, sample_to_three)
    print(result_three)

class VolumeConverter:
    def __init__(self, volume, unit):
        if unit not in ('liters', 'milliliters', 'cubic_meters', 'cubic_inches'):
            raise ValueError("Unit must be liters, milliliters, cubic_meters, or cubic_inches")
        self._volume = volume
        self._unit = unit

    @property
    def volume(self):
        return self._volume

    @property
    def unit(self):
        return self._unit

    def to_liters(self):
        if self._unit == 'liters':
            return self._volume
        elif self._unit == 'milliliters':
            return self._volume / 1000.0
        elif self._unit == 'cubic_meters':
            return self._volume * 1000.0
        elif self._unit == 'cubic_inches':
            return self._volume * 0.016387064
        return 0.0

    def to_milliliters(self):
        liters = self.to_liters()
        return liters * 1000.0

    def to_cubic_meters(self):
        if self._unit == 'cubic_meters':
            return self._volume
        elif self._unit == 'liters':
            return self._volume / 1000.0
        elif self._unit == 'milliliters':
            return self._volume / 1000000.0
        elif self._unit == 'cubic_inches':
            return self._volume * 1.6387064e-5
        return 0.0

    def to_cubic_inches(self):
        if self._unit == 'cubic_inches':
            return self._volume
        elif self._unit == 'liters':
            return self._volume / 0.016387064
        elif self._unit == 'milliliters':
            return self._volume / 0.016387064 / 1000.0
        elif self._unit == 'cubic_meters':
            return self._volume / 1.6387064e-5
        return 0.0

    def convert(self, target_unit):
        if target_unit == 'liters':
            return self.to_liters()
        elif target_unit == 'milliliters':
            return self.to_milliliters()
        elif target_unit == 'cubic_meters':
            return self.to_cubic_meters()
        elif target_unit == 'cubic_inches':
            return self.to_cubic_inches()
        raise ValueError("Target unit must be liters, milliliters, cubic_meters, or cubic_inches")

if __name__ == '__main__':
    converter = VolumeConverter(5, 'liters')
    print(converter.to_milliliters())
    print(converter.to_cubic_meters())

    converter2 = VolumeConverter(1, 'cubic_meters')
    print(converter2.to_cubic_inches())

    converter3 = VolumeConverter(1000, 'milliliters')
    print(converter3.to_liters())

