import math

def liters_to_milliliters(value: float) -> float:
    return value * 1000.0

def liters_to_cubic_meters(value: float) -> float:
    return value / 1000.0

def liters_to_gallons(value: float) -> float:
    return value * 0.264172052

def liters_to_cubic_inches(value: float) -> float:
    return value * 61.0237441

def cubic_inches_to_liters(value: float) -> float:
    return value / 61.0237441

def convert_volume(value: float, source_unit: str, target_unit: str) -> float:
    target_unit = target_unit.lower()
    source_unit = source_unit.lower()
    if source_unit == target_unit:
        return value
    liters = 0.0
    if source_unit == 'liters':
        liters = value
    elif source_unit == 'milliliters':
        liters = value / 1000.0
    elif source_unit == 'cubic_meters':
        liters = value * 1000.0
    elif source_unit == 'gallons':
        liters = value / 0.264172052
    elif source_unit == 'cubic_inches':
        liters = value / 61.0237441
    else:
        raise ValueError(f'Unknown source unit: {source_unit}')
    if target_unit == 'liters':
        return liters
    elif target_unit == 'milliliters':
        return liters * 1000.0
    elif target_unit == 'cubic_meters':
        return liters / 1000.0
    elif target_unit == 'gallons':
        return liters * 0.264172052
    elif target_unit == 'cubic_inches':
        return liters * 61.0237441
    else:
        raise ValueError(f'Unknown target unit: {target_unit}')
if __name__ == '__main__':
    result = convert_volume(100, 'liters', 'gallons')
    print(result)

class VolumeConverter:
    def __init__(self):
        self.units = {
            "liter": 1.0,
            "milliliter": 0.001,
            "cubic_meter": 1000.0,
            "gallon": 0.264172,
            "cubic_inch": 61.0237
        }

    def to_liters(self, value, unit):
        unit_lower = unit.lower()
        if unit_lower not in self.units:
            raise ValueError(f"Unknown unit: {unit}")
        return value / self.units[unit_lower]

    def from_liters(self, value, target_unit):
        target_lower = target_unit.lower()
        if target_lower not in self.units:
            raise ValueError(f"Unknown unit: {target_unit}")
        return value * self.units[target_lower]

    def convert(self, value, source_unit, target_unit):
        liters = self.to_liters(value, source_unit)
        return self.from_liters(liters, target_unit)

if __name__ == '__main__':
    converter = VolumeConverter()
    result1 = converter.convert(5, "gallon", "liter")
    result2 = converter.convert(1000, "milliliter", "liter")
    result3 = converter.convert(1, "cubic_meter", "gallon")
    result4 = converter.convert(10, "liter", "cubic_inch")
    result5 = converter.convert(50, "cubic_inch", "milliliter")
    print(result1)
    print(result2)
    print(result3)
    print(result4)
    print(result5)

class VolumeConverter:
    def __init__(self):
        self.liters_to_milliliters = 1000
        self.cubic_meters_to_cubic_inches = 61023.7441

    def liters_to_milliliters_conversion(self, liters):
        return liters * self.liters_to_milliliters

    def milliliters_to_liters_conversion(self, milliliters):
        return milliliters / self.liters_to_milliliters

    def cubic_meters_to_cubic_inches_conversion(self, cubic_meters):
        return cubic_meters * self.cubic_meters_to_cubic_inches

    def cubic_inches_to_cubic_meters_conversion(self, cubic_inches):
        return cubic_inches / self.cubic_meters_to_cubic_inches

