def convert_volume(value, from_unit, to_unit):
    units = ['l', 'ml', 'm3', 'gal', 'in3']
    from_unit = from_unit.lower()
    to_unit = to_unit.lower()

    if from_unit not in units or to_unit not in units:
        return "Invalid unit"

    if from_unit == to_unit:
        return value

    if from_unit == 'l':
        liters = value
    elif from_unit == 'ml':
        liters = value / 1000
    elif from_unit == 'm3':
        liters = value * 1000
    elif from_unit == 'gal':
        liters = value / 0.264172
    elif from_unit == 'in3':
        liters = value / 61.0237

    if to_unit == 'l':
        return liters
    elif to_unit == 'ml':
        return liters * 1000
    elif to_unit == 'm3':
        return liters / 1000
    elif to_unit == 'gal':
        return liters * 0.264172
    elif to_unit == 'in3':
        return liters * 61.0237

