import os
import tempfile

def convert_volume(volume_ml):
    liters = volume_ml / 1000.0
    cubic_meters = volume_ml / 1000000.0
    return liters, cubic_meters

def process_volume_file(filepath):
    results = []
    try:
        with open(filepath, 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        raise FileNotFoundError(f"The file {filepath} was not found.")
    except IOError as e:
        raise IOError(f"An error occurred while reading the file: {e}")

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            volume_ml = float(line)
            liters, cubic_meters = convert_volume(volume_ml)
            results.append((volume_ml, liters, cubic_meters))
        except ValueError:
            continue

    return results

def main():
    sample_values = ["1000", "500", "2000", "invalid", "3.5"]

    with tempfile.NamedTemporaryFile(mode='w', suffix='.txt', delete=False) as tmp:
        tmp_path = tmp.name
        for val in sample_values:
            tmp.write(f"{val}\n")

    try:
        results = process_volume_file(tmp_path)
        for volume_ml, liters, cubic_meters in results:
            print(f"{volume_ml} ml = {liters} liters = {cubic_meters} cubic meters")
    except Exception as e:
        print(e)
    finally:
        os.unlink(tmp_path)

if __name__ == '__main__':
    main()

def process_volumes(input_filename, sample_values):
    results = []
    try:
        with open(input_filename, 'r') as file:
            lines = file.readlines()
            for line in lines:
                line = line.strip()
                if not line:
                    continue
                try:
                    value = float(line)
                    liters = value * 3.78541
                    cubic_meters = value * 0.00378541
                    results.append((value, liters, cubic_meters))
                except ValueError:
                    continue
    except FileNotFoundError:
        for value in sample_values:
            liters = value * 3.78541
            cubic_meters = value * 0.00378541
            results.append((value, liters, cubic_meters))
    except IOError:
        for value in sample_values:
            liters = value * 3.78541
            cubic_meters = value * 0.00378541
            results.append((value, liters, cubic_meters))

    output_lines = []
    for val, lit, cm in results:
        output_lines.append(f"Original: {val}, Liters: {lit:.4f}, Cubic Meters: {cm:.6f}")
    return "\n".join(output_lines)

if __name__ == '__main__':
    input_file_name = "volumes.txt"
    sample_data = [10.0, 25.5, 100.0, -5.0, 0.0]
    output_result = process_volumes(input_file_name, sample_data)
    print(output_result)

def convert_volumes(volume_strings):
    results = []
    for volume_str in volume_strings:
        try:
            volume_liter = float(volume_str)
        except ValueError:
            continue
        cubic_meters = volume_liter / 1000.0
        results.append((volume_liter, cubic_meters))
    return results

def read_and_convert_volumes(filepath):
    try:
        with open(filepath, 'r') as f:
            lines = f.readlines()
    except FileNotFoundError:
        return []
    except IOError:
        return []

    volume_strings = [line.strip() for line in lines if line.strip()]
    return convert_volumes(volume_strings)

if __name__ == '__main__':
    sample_volumes = ["1.5", "250", "0.001", "invalid", "1000"]
    converted = convert_volumes(sample_volumes)
    for liter, cubic_meter in converted:
        print(f"{liter} liters = {cubic_meter} cubic meters")
